  const COMMANDS=[
    ['Home','Open the campus workspace','home'],['Marketplace','Browse listings','marketplace'],['Looking For','Post a request','requests'],['Community','Open Karma and community','community'],['Services','Open all utilities','services'],
    ['Rent & Borrow','Plan temporary access','rent'],['Barter & Trade','Create a trade offer','barter'],['Fair Price','Estimate resale value','fair-price'],['Lost & Found','Find likely report matches','lost-found'],['Starter Kits','Bundle your listings','starter-kits'],
    ['Fire Sale','Open semester clear-out','fire-sale'],['Vacation Hold','Plan storage','vacation-hold'],['Digital Vault','Open resources','vault'],['Impact','Open local impact','impact'],['Trust & Safety','Open safety center','safety'],['About','Read about UniTrade','about'],['Contributors','Meet the makers','contributors'],['Product Guide','Read and download the product guide','guide']
  ];

  const memoryStore=new Map(); let storageWarningShown=false;
  function saveData(key,value){try{localStorage.setItem(key,JSON.stringify(value));memoryStore.set(key,value);return true}catch(err){memoryStore.set(key,value);if(!storageWarningShown){storageWarningShown=true;console.warn('localStorage write failed; using in-memory fallback.',err);toast('Local storage is unavailable','UniTrade will keep your changes in this session. Enable site storage for persistence after closing the page.','info')}return false}}
  function loadData(key,fallback){try{const raw=localStorage.getItem(key);if(raw===null)return memoryStore.has(key)?memoryStore.get(key):fallback;const value=JSON.parse(raw);memoryStore.set(key,value);return value}catch(err){return memoryStore.has(key)?memoryStore.get(key):fallback}}
  function removeData(key){memoryStore.delete(key);try{localStorage.removeItem(key)}catch(err){console.warn('localStorage remove failed',err)}}
  function persist(){saveData(KEYS.user,state.user);saveData(KEYS.users,state.users);saveData(KEYS.listings,state.listings);saveData(KEYS.favorites,state.favorites);saveData(KEYS.requests,state.requests);saveData(KEYS.trades,state.trades);saveData(KEYS.notifications,state.notifications);saveData(KEYS.recentlyViewed,state.recentlyViewed);saveData(KEYS.theme,state.theme);saveData(KEYS.settings,state.settings);saveData(KEYS.karma,state.karma);saveData(KEYS.impact,state.impact);saveData(KEYS.searches,state.searches);saveData(KEYS.lostFound,state.lostFound);saveData(KEYS.vault,state.vault);saveData(KEYS.fireNotify,state.fireNotify);saveData(KEYS.rentPlan,state.rentPlan);saveData(KEYS.compare,state.compare);saveData(KEYS.storageVersion,STORAGE_VERSION);saveData(KEYS.lastSession,{at:new Date().toISOString(),route:currentRoute()})}
  function clearLocalData(){Object.entries(KEYS).forEach(([,key])=>removeData(key));removeData('unitrade_sample_content_seed_v1');location.hash='#home';location.reload()}
  function resetOnVersion(){saveData(KEYS.storageVersion,STORAGE_VERSION)}
  function isLegacySample(item){if(!item)return false;const id=String(item.id||'');const author=String(item.author||'');const seller=String(item.seller||'');return item.isSample===true || /^sample(?:_|-)/i.test(id) || /^sample (seller|giver|lender|trader|contributor|requester)$/i.test(author) || /^sample (seller|giver|lender|trader|contributor|requester)$/i.test(seller)}
  function removeLegacySampleContent(){
    const oldSeed=loadData('unitrade_sample_content_seed_v1',false);
    const before={listings:state.listings.length,requests:state.requests.length,lostFound:state.lostFound.length,vault:state.vault.length};
    const sampleIds=new Set(state.listings.filter(isLegacySample).map(x=>x.id));
    state.listings=state.listings.filter(x=>!isLegacySample(x));
    state.requests=state.requests.filter(x=>!isLegacySample(x));
    state.lostFound=state.lostFound.filter(x=>!isLegacySample(x));
    state.vault=state.vault.filter(x=>!isLegacySample(x));
    state.users=state.users.filter(x=>!isLegacySample(x));
    state.favorites=state.favorites.filter(id=>!sampleIds.has(id));
    state.compare=state.compare.filter(id=>!sampleIds.has(id));
    state.recentlyViewed=state.recentlyViewed.filter(id=>!sampleIds.has(id));
    state.notifications=state.notifications.filter(n=>!/sample bundle|sample content|sample listing|sample request|illustrative only/i.test(`${n.title||''} ${n.text||''}`));
    const removed=before.listings!==state.listings.length||before.requests!==state.requests.length||before.lostFound!==state.lostFound.length||before.vault!==state.vault.length||!!oldSeed;
    if(removed&&(oldSeed || sampleIds.size>0 || state.karma===820))state.karma=0;
    removeData('unitrade_sample_content_seed_v1');
    saveData(KEYS.listings,state.listings);saveData(KEYS.requests,state.requests);saveData(KEYS.lostFound,state.lostFound);saveData(KEYS.vault,state.vault);saveData(KEYS.users,state.users);saveData(KEYS.favorites,state.favorites);saveData(KEYS.compare,state.compare);saveData(KEYS.recentlyViewed,state.recentlyViewed);saveData(KEYS.notifications,state.notifications);saveData(KEYS.karma,state.karma);
    window.__unitradeSampleCleanupOccurred=!!removed;
  }
  function hydrate(){resetOnVersion();state.user=loadData(KEYS.user,null);state.users=loadData(KEYS.users,[]);state.listings=loadData(KEYS.listings,[]);state.favorites=loadData(KEYS.favorites,[]);state.requests=loadData(KEYS.requests,[]);state.trades=loadData(KEYS.trades,[]);state.notifications=loadData(KEYS.notifications,[]);state.recentlyViewed=loadData(KEYS.recentlyViewed,[]);state.theme=loadData(KEYS.theme,'dark');state.settings={...state.settings,...loadData(KEYS.settings,{})};state.karma=loadData(KEYS.karma,0);state.impact=loadData(KEYS.impact,{});state.searches=loadData(KEYS.searches,[]);state.lostFound=loadData(KEYS.lostFound,[]);state.vault=loadData(KEYS.vault,[]);state.fireNotify=loadData(KEYS.fireNotify,false);state.rentPlan=loadData(KEYS.rentPlan,null);state.compare=loadData(KEYS.compare,[]);removeLegacySampleContent();applyTheme();applySettings()}

  function relativeDate(daysOffset=0){const d=new Date();d.setDate(d.getDate()+daysOffset);return d.toISOString().slice(0,10)}
  function toast(title,message='',type='info'){const wrap=document.createElement('div');wrap.className=`toast toast-${type}`;wrap.innerHTML=`<span class="toast-icon">${type==='error'?'!':type==='success'?'✓':'i'}</span><div><strong>${escapeHTML(title)}</strong><small>${escapeHTML(message)}</small></div><button aria-label="Dismiss">×</button>`;$('#toastRegion')?.appendChild(wrap);wrap.querySelector('button')?.addEventListener('click',()=>wrap.remove());setTimeout(()=>wrap.remove(),4200)}
  function addNotification(title,text,unread=true){state.notifications.unshift({id:`n_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,title,text,time:'Just now',unread});state.notifications=state.notifications.slice(0,40);persist();renderNotifications();renderNotificationCount()}
  function renderNotificationCount(){const count=state.notifications.filter(n=>n.unread).length;$('#notificationCount').textContent=count;$('#notificationCount').classList.toggle('hidden',count===0)}
  function renderNotifications(){$('#notificationList').innerHTML=state.notifications.length?state.notifications.map(n=>`<article class="notification-item"><span class="notification-dot ${n.unread?'is-new':''}"></span><div><b>${escapeHTML(n.title)}</b><p>${escapeHTML(n.text)}</p><small>${escapeHTML(n.time||'')}</small></div></article>`).join(''):'<div class="empty-state compact"><h3>No notifications yet</h3><p>New listing saves, help offers and account activity will appear here.</p></div>'}

  function applyTheme(){document.documentElement.dataset.theme=state.theme==='light'?'light':'dark';if($('#themeIcon'))$('#themeIcon').textContent=state.theme==='light'?'☼':'◐'}
  function toggleTheme(){state.theme=state.theme==='light'?'dark':'light';applyTheme();persist();toast(`${state.theme==='light'?'Light':'Dark'} theme enabled`,'Your preference was saved locally.','success')}
  function applySettings(){document.body.classList.toggle('compact-mode',!!state.settings.compact);document.body.classList.toggle('reduced-motion-user',!!state.settings.reducedMotion);if($('#compactCards'))$('#compactCards').checked=!!state.settings.compact;if($('#savedAlerts'))$('#savedAlerts').checked=!!state.settings.savedAlerts;if($('#reducedMotion'))$('#reducedMotion').checked=!!state.settings.reducedMotion}

  function currentRoute(){const raw=(location.hash||'#home').slice(1).split('?')[0];return ROUTES.has(raw)?raw:'home'}
  function routeLabel(route){return ({home:'Home',marketplace:'Marketplace',requests:'Looking For',community:'Community',services:'Services',rent:'Rent & Borrow',barter:'Barter & Trade','fair-price':'Fair Price','lost-found':'Lost & Found','starter-kits':'Starter Kits','fire-sale':'Fire Sale','vacation-hold':'Vacation Hold',vault:'Digital Vault',impact:'Campus Impact',safety:'Trust & Safety',about:'About UniTrade',contributors:'Contributors',guide:'Product Guide'}[route]||'UniTrade')}
  function navigate(route,{target=null,fromTour=false}={}){const safe=ROUTES.has(route)?route:'home';if(currentRoute()!==safe)location.hash=`#${safe}`;renderRoute(safe);setTimeout(()=>{const el=target?$('#'+target):$(`#view-${safe}`);el?.scrollIntoView({behavior:state.settings.reducedMotion?'auto':'smooth',block:target?'center':'start'});if(fromTour&&target)spotlight(el)},90)}
  function renderRoute(route=currentRoute()){$$('.page-view').forEach(v=>v.hidden=v.dataset.view!==route);$$('.desktop-nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===route||(SERVICE_ROUTES.has(route)&&a.dataset.route==='services')));$$('.feature-rail a').forEach(a=>a.classList.toggle('active',a.dataset.route===route));$$('.mobile-nav-links a').forEach(a=>a.classList.toggle('active',a.dataset.route===route||(SERVICE_ROUTES.has(route)&&a.dataset.route==='services')));if(route==='marketplace')renderListings();if(route==='requests')renderRequests();if(route==='lost-found')renderLostFoundBoard();if(route==='community')renderCommunity();if(route==='impact')renderImpact();if(route==='vault')renderVault();if(route==='starter-kits')renderBundleCards();if(route==='fire-sale')renderFireSale();if(route==='barter'){renderTradeOptions();renderTradeHistory()}if(route==='home')syncHomeCounts();document.title=`${routeLabel(route)} — UniTrade`}
  function initNavigation(){const links=[['home','Home'],['marketplace','Marketplace'],['requests','Looking For'],['community','Community'],['services','Services'],['impact','Impact'],['safety','Safety'],['about','About'],['contributors','Contributors'],['guide','Product Guide'],['rent','Rent & Borrow'],['barter','Barter & Trade'],['fair-price','Fair Price'],['lost-found','Lost & Found'],['starter-kits','Starter Kits'],['fire-sale','Fire Sale'],['vacation-hold','Vacation Hold'],['vault','Digital Vault']];$('#mobileNavLinks').innerHTML=links.map(([r,l])=>`<a href="#${r}" data-route="${r}">${escapeHTML(l)}</a>`).join('');document.addEventListener('click',e=>{const routeEl=e.target.closest('[data-route]');if(routeEl){e.preventDefault();navigate(routeEl.dataset.route);closeMobileNav()}});window.addEventListener('hashchange',()=>renderRoute())}

  function openModal(id,focusSelector){const root=$('#modalRoot');if(!root)return;root.hidden=false;$$('#modalRoot > .modal').forEach(m=>m.hidden=true);const modal=$('#'+id);if(!modal)return;modal.hidden=false;modal.dataset.previousFocus=document.activeElement?.id||'';document.body.classList.add('modal-open');setTimeout(()=>{const focus=focusSelector?modal.querySelector(focusSelector):modal.querySelector('input,button,select,textarea');focus?.focus()},60)}
  function closeModal(){const root=$('#modalRoot');if(!root||root.hidden)return;const active=root.querySelector('.modal:not([hidden])');const previous=active?.dataset.previousFocus;root.hidden=true;document.body.classList.remove('modal-open');$('#tourSpotlight').hidden=true;if(previous&&$('#'+previous))$('#'+previous).focus()}
  function closeCommandPalette(){if($('#commandPalette').hidden)return;$('#commandPalette').hidden=true}
  function openCommandPalette(){closeModal();$('#commandPalette').hidden=false;renderCommands('');setTimeout(()=>$('#paletteInput')?.focus(),40)}
  function openShortcuts(){renderShortcuts();openModal('shortcutsModal')}
  function closeMobileNav(){$('#mobileNav').hidden=true;$('#mobileMenuBtn').setAttribute('aria-expanded','false')}

  function resetFilters(){state.search='';state.filterMode='all';state.filterCategory='all';state.filterCondition='all';state.sort='newest';if($('#globalSearch'))$('#globalSearch').value='';if($('#heroSearch'))$('#heroSearch').value='';if($('#categoryFilter'))$('#categoryFilter').value='all';if($('#conditionFilter'))$('#conditionFilter').value='all';if($('#sortFilter'))$('#sortFilter').value='newest';$$('.filter-select[data-filter-mode]').forEach(x=>x.classList.toggle('active',x.dataset.filterMode==='all'));renderListings()}
  function populateCategories(){const cats=[...new Set(state.listings.map(x=>x.category).filter(Boolean))].sort();if($('#categoryFilter'))$('#categoryFilter').innerHTML='<option value="all">All categories</option>'+cats.map(x=>`<option value="${escapeHTML(x)}">${escapeHTML(x)}</option>`).join('')}
  function visibleListings(){let items=state.listings.slice();const q=state.search.trim().toLowerCase();if(q)items=items.filter(x=>[x.title,x.category,x.description,x.seller,x.hostel,x.mode,...(x.tags||[])].join(' ').toLowerCase().includes(q));if(state.filterMode!=='all')items=items.filter(x=>x.mode===state.filterMode);if(state.filterCategory!=='all')items=items.filter(x=>x.category===state.filterCategory);if(state.filterCondition!=='all')items=items.filter(x=>x.condition===state.filterCondition);if(state.sort==='priceLow')items.sort((a,b)=>(a.price||0)-(b.price||0));else if(state.sort==='nearest')items.sort((a,b)=>(parseInt(a.distance)-parseInt(b.distance)));else if(state.sort==='impact')items.sort((a,b)=>(b.impactWeight||0)-(a.impactWeight||0));else items.sort((a,b)=>String(b.created||'').localeCompare(String(a.created||'')));return items}
  function listingPriceText(x){if(x.mode==='borrow')return 'Borrow';if(x.mode==='barter')return 'Barter';if(x.mode==='free'||Number(x.price)===0)return 'Free';return x.mode==='rent'?`${money(x.price)} / day`:money(x.price)}
  function listingCard(x){const fav=state.favorites.includes(x.id),cmp=state.compare.includes(x.id);const cat=normaliseText(x.category);const productIcon=/electronic|phone|laptop|computer|calculator|gadget/.test(cat)?'⌁':/book|academic|note|stationery|study/.test(cat)?'▤':/furniture|table|chair|mattress/.test(cat)?'▰':/hostel|kitchen|bedding|home/.test(cat)?'⌂':/transport|cycle|bicycle|scooter/.test(cat)?'↗':/lab|equipment/.test(cat)?'⚗':/digital|resource/.test(cat)?'▧':'✦';return `<article class="listing-card" data-id="${escapeHTML(x.id)}"><div class="listing-visual product-visual category-${escapeHTML(cat.replace(/\s+/g,'-')||'other')}"><div class="listing-tags"><span class="pill pill-mode">${escapeHTML((x.mode||'buy').replace(/^./,c=>c.toUpperCase()))}</span>${x.legacy?'<span class="pill pill-legacy">Legacy item</span>':''}</div><button class="favorite-btn ${fav?'active':''}" data-favorite="${escapeHTML(x.id)}" aria-label="${fav?'Remove from favorites':'Save item'}">${fav?'♥':'♡'}</button><div class="listing-art tone-${escapeHTML(x.artTone||'cyan')}" aria-hidden="true">${escapeHTML(x.art && x.art !== '✦' ? x.art : productIcon)}</div></div><div class="listing-body"><div class="listing-meta"><span>${escapeHTML(x.category||'Other')}</span><span>${escapeHTML(x.distance||'Campus')}</span></div><h3>${escapeHTML(x.title)}</h3><p>${escapeHTML(x.description)}</p><div class="listing-foot"><div class="price">${escapeHTML(listingPriceText(x))}<small>${x.originalPrice?`${money(x.originalPrice)} original`:escapeHTML(x.availability||'Available')}</small></div><div class="listing-actions"><button class="tiny-action" data-listing-action="view" data-id="${escapeHTML(x.id)}">View</button><button class="tiny-action" data-listing-action="share" data-id="${escapeHTML(x.id)}">Share</button><button class="tiny-action" data-listing-action="report" data-id="${escapeHTML(x.id)}">Report</button>${state.user&&(x.ownerUid===state.user.id||x.ownerUid===cloudAuth()?.currentUser?.uid)?`<button class="tiny-action danger-action" data-listing-action="delete" data-id="${escapeHTML(x.id)}">Delete</button>`:''}</div></div><div class="listing-meta listing-meta-bottom"><span>${escapeHTML(x.hostel||'Campus')}</span><span>${escapeHTML(x.condition||'Condition not set')}</span><button class="compare-chip ${cmp?'selected':''}" data-compare-id="${escapeHTML(x.id)}">${cmp?'✓ Comparing':'Compare'}</button></div></div></article>`}
  function renderListings(){const items=visibleListings();$('#searchCount').textContent=`${items.length} ${items.length===1?'listing':'listings'}`;$('#clearSearch').classList.toggle('hidden',!state.search);$('#listingGrid').innerHTML=items.map(listingCard).join('');$('#listingEmpty').hidden=items.length!==0;$('#listingFilterInsight').textContent=state.listings.length?'Adjust filters or search to narrow the results.':'Your marketplace is empty. Create the first listing after signing in.';bindListingActions();$('#compareBtn').disabled=state.compare.length!==2;$('#compareTray').querySelector('span').textContent=state.compare.length?`${state.compare.length} selected for comparison`:'Select up to two items to compare'}
  function bindListingActions(){$$('.favorite-btn').forEach(b=>b.addEventListener('click',()=>toggleFavorite(b.dataset.favorite)));$$('[data-listing-action="view"]').forEach(b=>b.addEventListener('click',()=>openListing(b.dataset.id)));$$('[data-listing-action="share"]').forEach(b=>b.addEventListener('click',()=>shareListing(b.dataset.id)));$$('[data-listing-action="report"]').forEach(b=>b.addEventListener('click',()=>openReport(b.dataset.id)));$$('[data-listing-action="delete"]').forEach(b=>b.addEventListener('click',()=>deleteOwnListing(b.dataset.id)));$$('[data-compare-id]').forEach(b=>b.addEventListener('click',()=>toggleCompare(b.dataset.compareId)));}
  async function deleteOwnListing(id){const item=state.listings.find(x=>x.id===id);if(!item||!state.user||!(item.ownerUid===state.user.id||item.ownerUid===cloudAuth()?.currentUser?.uid))return toast('Not allowed','You can only delete your own listing.','error');if(!confirm(`Delete “${item.title}”? This cannot be undone.`))return;try{if(cloudReady())await cloudDb().collection('listings').doc(id).delete();state.listings=state.listings.filter(x=>x.id!==id);persist();renderListings();renderProfile();renderTradeOptions();toast('Listing deleted','Your listing was removed.','success')}catch(e){toast('Delete failed',e.message||'Check Firestore rules.','error')}}
  function toggleFavorite(id){if(!state.user){showLogin();return}const i=state.favorites.indexOf(id);if(i>=0){state.favorites.splice(i,1);toast('Removed from saved items','The listing is no longer in your favorites.')}else{state.favorites.push(id);addNotification('Listing saved','The listing was added to your saved items.');toast('Saved','You can find it again from your profile.','success')}persist();renderListings();renderProfile()}
  function toggleCompare(id){if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else{if(state.compare.length>=2)return toast('Compare limit reached','Choose up to two listings.','error');state.compare.push(id)}persist();renderListings()}
  function openCompare(){const items=state.compare.map(id=>state.listings.find(x=>x.id===id)).filter(Boolean);if(items.length!==2)return toast('Choose two items','Select two listings to compare.','info');$('#detailContent').innerHTML=`<span class="section-kicker">Comparison</span><h2 id="detailTitle">Two campus options, side by side.</h2><div class="impact-detail-grid">${items.map(x=>`<div class="glass-panel impact-card"><span class="section-kicker">${escapeHTML(x.category)}</span><h3>${escapeHTML(x.title)}</h3><ul class="clean-list"><li>Price / mode: ${escapeHTML(listingPriceText(x))}</li><li>Condition: ${escapeHTML(x.condition||'Not specified')}</li><li>Location: ${escapeHTML(x.hostel||'Campus')} · ${escapeHTML(x.distance||'Nearby')}</li><li>Mode: ${escapeHTML(x.mode||'Buy')}</li></ul></div>`).join('')}</div>`;openModal('detailModal')}
  function openListing(id){const x=state.listings.find(v=>v.id===id);if(!x)return;state.recentlyViewed=[id,...state.recentlyViewed.filter(v=>v!==id)].slice(0,10);persist();$('#detailContent').innerHTML=`<span class="section-kicker">${escapeHTML(x.category)} · ${escapeHTML(x.mode)}</span><h2 id="detailTitle">${escapeHTML(x.title)}</h2><p>${escapeHTML(x.description)}</p><div class="impact-detail-grid"><div class="glass-panel impact-card"><span class="section-kicker">Listing details</span><h3>${escapeHTML(listingPriceText(x))}</h3><ul class="clean-list"><li>Condition: ${escapeHTML(x.condition||'Not specified')}</li><li>Availability: ${escapeHTML(x.availability||'Available')}</li><li>Pickup: ${escapeHTML(x.hostel||'Campus')} · ${escapeHTML(x.distance||'Nearby')}</li><li>Seller: ${x.ownerUid?`<button class="text-btn" id="detailSellerProfileBtn">${escapeHTML(x.seller||'Campus member')}</button>`:escapeHTML(x.seller||'Campus member')}</li></ul></div><div class="glass-panel impact-card"><span class="section-kicker">Next step</span><h3>Start a responsible campus conversation.</h3><p>Clarify condition, timing, price, accessories and handover location before completing the exchange.</p><div class="page-actions"><button class="btn btn-primary" id="detailContactBtn">Contact seller</button><button class="btn btn-secondary" id="detailSaveBtn">${state.favorites.includes(x.id)?'Saved':'Save item'}</button></div></div></div>`;openModal('detailModal');$('#detailContactBtn').addEventListener('click',()=>{closeModal();contactSeller(x.id)});$('#detailSaveBtn').addEventListener('click',()=>{toggleFavorite(x.id);closeModal()});$('#detailSellerProfileBtn')?.addEventListener('click',()=>{if(!cloudAuth()?.currentUser){closeModal();showLogin();return}window.dispatchEvent(new CustomEvent('unitrade:show-profile',{detail:{uid:x.ownerUid}}))})}
  function shareListing(id){const x=state.listings.find(v=>v.id===id);if(!x)return;const url=`${location.origin}${location.pathname}#marketplace`;if(navigator.share){navigator.share({title:`${x.title} · UniTrade`,text:`${x.title} · ${x.hostel||'Campus'} · ${x.distance||'Nearby'}`,url}).catch(()=>{})}else if(navigator.clipboard){navigator.clipboard.writeText(url).then(()=>toast('Link copied','Marketplace link copied to your clipboard.','success')).catch(()=>toast('Share unavailable','Copy the page URL manually.','error'))}}
  function contactSeller(id){const x=state.listings.find(v=>v.id===id);if(!x)return;if(!state.user){showLogin();return}if(x.ownerUid&&x.ownerUid!==cloudAuth()?.currentUser?.uid){window.dispatchEvent(new CustomEvent('unitrade:contact',{detail:{uid:x.ownerUid,listingId:id}}));return}toast('This is your listing','You cannot message yourself.','info')}
  function openReport(id){if(!state.user){showLogin();return}$('#reportForm').dataset.listingId=id;openModal('safetyModal')}

  function renderRequests(){const list=state.requests;$('#requestCount').textContent=list.length;$('#requestList').innerHTML=list.length?list.map(r=>`<article class="request-card"><div class="request-card-top"><span class="pill">${escapeHTML(r.preference)}</span><span class="tiny-label">${escapeHTML(dateLabel(r.date))}</span></div><h3>${escapeHTML(r.item)}</h3><p>${escapeHTML(r.description)}</p><div class="request-tags"><span>${r.budget?`Up to ${money(r.budget)}`:'Budget flexible'}</span><span>${escapeHTML(r.hostel||'Campus-wide')}</span><span>by ${escapeHTML(r.author||'You')}</span></div><button class="btn btn-secondary" data-help-request="${escapeHTML(r.id)}">I can help</button></article>`).join(''):'<div class="empty-state"><h3>No requests yet</h3><p>Once you publish a Looking For request, it will appear here.</p><button class="btn btn-primary" id="emptyRequestBtn">Create a request</button></div>';$$('[data-help-request]').forEach(b=>b.addEventListener('click',()=>{if(!state.user)return showLogin();const req=state.requests.find(r=>r.id===b.dataset.helpRequest);addNotification('Help offer recorded','Your interest was stored locally for this request.');toast('Thanks for helping','A future secure messaging layer can connect both students.','success')}));$('#emptyRequestBtn')?.addEventListener('click',()=>state.user?openModal('requestModal'):showLogin())}
  async function submitRequest(form){if(!state.user){closeModal();return showLogin()}const f=new FormData(form);const req={item:String(f.get('item')).trim(),budget:Number(f.get('budget')||0),date:String(f.get('date')||''),hostel:String(f.get('hostel')||'Campus-wide'),preference:String(f.get('preference')),description:String(f.get('description')).trim(),author:state.user.name,ownerName:state.user.name,status:'open'};if(!req.item||!req.description)return;try{req.id=await cloudWrite('requests',req);state.requests.unshift({...req,created:new Date().toISOString()});addKarma(5,'Request posted');persist();form.reset();closeModal();renderRequests();renderImpact();toast('Request published','Your request was saved to Firebase.','success')}catch(err){console.error(err);toast('Request not saved',err.message||'Check Firestore rules and sign-in.','error')}}

  function addKarma(points,reason){state.karma=(Number(state.karma)||0)+Number(points||0);persist();if(points>0)addNotification(`+${points} Karma`,reason,false);renderCommunity()}
  function renderCommunity(){const points=Number(state.karma)||0;const level=points>=1000?'Sustainability Legend':points>=700?'Campus Hero':points>=450?'Reuser':points>0?'Helper':'New member';const next=points<450?450-points:points<700?700-points:points<1000?1000-points:0;$('#karmaCardPoints').textContent=points;$('#karmaLevel').textContent=level;$('#karmaProgressBar').style.width=points?`${Math.min(100,Math.max(5,Math.round((points%250)/2.5)))}%`:'0%';$('#karmaNextText').textContent=next?`${next} points to the next level.`:points?'Top level reached.':'Create a helpful listing or request to start earning Karma.';$('#leaderboard').innerHTML=points&&state.user?`<div class="leader-row"><span>1</span><div><b>${escapeHTML(state.user.name)}</b><small>${escapeHTML(level)}</small></div><strong class="leader-score">${points}</strong></div>`:'<div class="empty-state compact"><h3>No community ranking yet</h3><p>Campus ranking becomes useful after real accounts begin contributing.</p></div>';const metrics=[['Your listings',state.listings.length],['Your requests',state.requests.length],['Saved items',state.favorites.length],['Your resources',state.vault.length]];const max=Math.max(...metrics.map(x=>x[1]),1);const host=$('#communityTrendBars');if(host)host.innerHTML=metrics.map(([label,value])=>`<div><span>${label}</span><i><b style="width:${Math.round(value/max*100)}%"></b></i><strong>${value}</strong></div>`).join('')}

  function renderImpact(){const listings=state.listings;const requests=state.requests;const free=listings.filter(x=>x.mode==='free').length;const reused=listings.reduce((n,x)=>n+Number(x.impactWeight||1),0);const savings=listings.reduce((n,x)=>n+Math.max(0,Number(x.originalPrice||0)-Number(x.price||0)),0);const waste=Math.round(reused*0.8);const students=new Set(listings.map(x=>x.seller).filter(Boolean)).size+(requests.length?Math.min(requests.length,3):0);$('#impactSavings').textContent=money(savings);$('#impactReused').textContent=reused;$('#impactFree').textContent=free;$('#impactWaste').textContent=`${waste} kg` ;$('#impactStudents').textContent=students;$('#impactListings').textContent=listings.length;$('#impactOrbValue').textContent=reused;$('#impactHeadline').textContent=reused?`${reused} listing impact units are calculated from records stored on this device. Environmental values are estimates.`:'Your impact story starts at zero. Figures grow as you add your own listings and requests.';state.impact={savings,reused,free,waste,students};saveData(KEYS.impact,state.impact)}
  function syncHomeCounts(){const ownListings=state.user?state.listings.filter(x=>x.seller===state.user.name):state.listings;const ownRequests=state.user?state.requests.filter(x=>x.author===state.user.name):state.requests;const saved=state.favorites.length;const listings=ownListings.length,requests=ownRequests.length,total=listings+saved+requests;$('#heroListingsCount').textContent=listings;$('#heroSavedCount').textContent=saved;$('#heroWorkspaceCount').textContent=listings;$('#heroWorkspaceStatus').textContent=state.user?'Workspace active':'Your campus workspace';$('#heroWorkspaceHeadline').textContent=state.user?`Welcome, ${escapeHTML(state.user.name.split(' ')[0])}.`:'Explore the campus marketplace.';$('#heroWorkspaceSub').textContent=state.user?`${listings} of your listings, ${saved} saved items and ${requests} of your requests are stored on this device.`:`${listings} listings are stored on this device. Create an account to start adding your own.`;$('#heroActivityText').textContent=total?`${total} local interactions`:'No marketplace activity yet';$('#homeCommunityCount').textContent=total;$('#heroStorageState').textContent=state.user?'Active':'Ready';$('#homePulseList').innerHTML=`<div><span>Your listings</span><strong>${listings}</strong></div><div><span>Your requests</span><strong>${requests}</strong></div><div><span>Saved items</span><strong>${saved}</strong></div>`;$('#heroAvatarStack').innerHTML=state.user?`<span>${escapeHTML(initials(state.user.name))}</span>`:'<span>U</span>';renderImpact()}

  function renderBundleCards(){const owned=state.user?state.listings.filter(x=>x.seller===state.user.name):[];const total=owned.slice(0,4).reduce((n,x)=>n+Number(x.price||0),0);const eligible=Math.min(owned.length,4);const potential=eligible>=2?Math.round(total*.1):0;$('#bundleSourceCount').textContent=owned.length;$('#bundleEligibleCount').textContent=eligible;$('#bundlePotentialSaving').textContent=money(potential);if(owned.length<2){$('#bundleGrid').innerHTML='<div class="empty-state"><h3>Build your first bundle</h3><p>Starter Kits are created from your own listings. Add at least two compatible items in Marketplace first.</p><button class="btn btn-primary" data-route="marketplace">Create a listing</button></div>';return}const group=owned.slice(0,4);const bundle=Math.round(total*.9);$('#bundleGrid').innerHTML=`<article class="bundle-mini"><span class="section-kicker">Your bundle</span><h3>${escapeHTML(group.map(x=>x.title).join(' + '))}</h3><p>${group.map(x=>escapeHTML(x.category||'Other')).join(' · ')}</p><footer><div><b>${money(bundle)}</b><small> · ${money(Math.max(0,total-bundle))} potential bundle saving</small></div><button class="btn btn-secondary" id="saveBundleGenerated">Save bundle idea</button></footer></article>`;$('#saveBundleGenerated').addEventListener('click',()=>{addNotification('Starter Kit saved','Your current listing group was saved as a bundle idea.');toast('Bundle saved','Your Starter Kit idea is stored locally.','success')})}
  function renderFireSale(){const owned=state.user?state.listings.filter(x=>x.seller===state.user.name&&Number(x.price||0)>0):[];$('#fireSaleGrid').innerHTML=owned.length?owned.slice(0,8).map(x=>listingCard({...x,fire:true})).join(''):'<div class="empty-state"><h3>No Fire Sale listings yet</h3><p>Create a listing first. When you are ready for a faster semester-end handover, it can be surfaced here.</p><button class="btn btn-primary" id="fireCreateBtn">Create a listing</button></div>';bindListingActions();$('#fireCreateBtn')?.addEventListener('click',()=>state.user?openModal('listingModal'):showLogin())}

  function renderVault(){const q=($('#vaultSearch')?.value||'').toLowerCase();const active=$('.vault-tags .filter-select.active')?.dataset.vaultFilter||'all';const rows=state.vault.filter(v=>(active==='all'||String(v.access).toLowerCase()===active)&&[v.title,v.subject,v.semester,v.author].join(' ').toLowerCase().includes(q));$('#vaultGrid').innerHTML=rows.length?rows.map(v=>`<article class="vault-card"><div class="vault-card-head"><div class="doc-mark">▣</div></div><h3>${escapeHTML(v.title)}</h3><p>${escapeHTML(v.subject)} · ${escapeHTML(v.semester)}</p><footer><span>${escapeHTML(v.access)} · ${escapeHTML(v.author||'You')}</span><button class="text-btn" data-vault-preview="${escapeHTML(v.id)}">Preview →</button></footer></article>`).join(''):'<div class="empty-state"><h3>Your Digital Vault is empty</h3><p>Add notes or resources you own or are authorized to share. Keep the copyright and academic-integrity rules visible.</p><button class="btn btn-primary" id="emptyVaultBtn">Add a resource</button></div>';$$('[data-vault-preview]').forEach(b=>b.addEventListener('click',()=>{const v=state.vault.find(x=>x.id===b.dataset.vaultPreview);if(!v)return;$('#detailContent').innerHTML=`<span class="section-kicker">Digital Vault</span><h2 id="detailTitle">${escapeHTML(v.title)}</h2><p>${escapeHTML(v.subject)} · ${escapeHTML(v.semester)}</p><div class="disclaimer"><b>Sharing note</b><span>${escapeHTML(v.note)}</span></div><p class="mini-note">This workspace stores resource metadata locally. Secure file storage and access control should be connected server-side before distributing real documents.</p>`;openModal('detailModal')}));$('#emptyVaultBtn')?.addEventListener('click',()=>state.user?openModal('vaultModal'):showLogin())}

  function renderTradeOptions(){const mine=$('#tradeMine'),target=$('#tradeTarget');if(!mine||!target)return;const mineItems=state.user?state.listings.filter(x=>x.seller===state.user.name):[];mine.innerHTML=mineItems.length?mineItems.map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.title)}</option>`).join(''):'<option value="">Sign in and create a listing</option>';target.innerHTML=state.listings.length?state.listings.map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(x.title)} · ${escapeHTML(x.hostel||'Campus')}</option>`).join(''):'<option value="">No target listings yet</option>';updateTradeSummary()}
