  function renderTradeHistory(){$('#tradeHistory').innerHTML=state.trades.length?state.trades.map(t=>`<article class="trade-row"><div><b>${escapeHTML(t.mineTitle||'Your item')}</b><small>for ${escapeHTML(t.targetTitle||'Target item')} · ${escapeHTML(t.status||'Sent')}</small></div><span>${escapeHTML(t.date||'')}</span></article>`).join(''):'<div class="empty-state compact"><h3>No trade offers yet</h3><p>Your sent offers will appear here.</p></div>'}

  function submitTrade(){if(!state.user)return showLogin();const mine=state.listings.find(x=>x.id===$('#tradeMine').value),target=state.listings.find(x=>x.id===$('#tradeTarget').value);if(!mine||!target)return toast('Choose two listings','Select your listing and the target listing first.','error');if(mine.id===target.id)return toast('Choose different listings','The target must be different from your own listing.','error');const trade={id:`t_${Date.now()}`,mine:mine.id,target:target.id,mineTitle:mine.title,targetTitle:target.title,message:$('#tradeMessage').value.trim(),status:'Sent',date:new Date().toLocaleDateString('en-IN')};state.trades.unshift(trade);persist();$('#tradeMessage').value='';renderTradeHistory();addNotification('Trade offer sent',`Your offer for ${target.title} was stored locally.`);toast('Trade offer sent','The offer is now in your trade history.','success')}

  function calculateFairPrice(){const f=new FormData($('#fairPriceForm'));const original=Math.max(0,Number(f.get('price')||0)),age=Math.max(0,Number(f.get('age')||0)),condition=String(f.get('condition')),demand=String(f.get('demand')),category=String(f.get('category'));const conditionFactor={Excellent:.8,Good:.68,Fair:.5}[condition]||.6;const ageFactor=Math.max(.25,1-age*.08);const demandFactor={High:1.12,Medium:1,Low:.88}[demand]||1;const mid=Math.max(0,original*conditionFactor*ageFactor*demandFactor);const low=Math.round(mid*.9/10)*10,high=Math.round(mid*1.12/10)*10,confidence=Math.min(93,Math.max(54,Math.round(62+conditionFactor*20-age*3+(demand==='High'?6:0))));$('#fairPriceResult').innerHTML=`<span class="section-kicker">Suggested range</span><h2>${money(low)} – ${money(high)}</h2><div class="confidence-bar"><span style="width:${confidence}%"></span></div><p><b>${confidence}% confidence</b> · Based on ${escapeHTML(category.toLowerCase())}, ${escapeHTML(condition.toLowerCase())} condition, ${age} year${age===1?'':'s'} of age and ${escapeHTML(demand.toLowerCase())} demand.</p><div class="disclaimer"><b>Important</b><span>This is a transparent estimate for pricing decisions, not a guaranteed market value.</span></div>`}

  function similarity(a,b){const tokens=t=>new Set(String(t||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(w=>w.length>2));const A=tokens(a),B=tokens(b);if(!A.size||!B.size)return 0;let common=0;A.forEach(x=>{if(B.has(x))common++});return common/(new Set([...A,...B]).size||1)}
  function renderLostFoundBoard(){const host=$('#matchStack');if(!host)return;const reports=state.lostFound.slice(0,8);host.innerHTML=reports.length?reports.map(x=>`<article class="match-card glass-panel"><div><span class="section-kicker">${escapeHTML(x.type)} report · ${escapeHTML(x.category||'Other')}</span><h4>${escapeHTML(x.description)}</h4><p>${escapeHTML(x.location)} · ${escapeHTML(x.color||'Colour not listed')}</p><small>${escapeHTML(dateLabel(x.date))}</small></div><span class="history-status">Saved</span></article>`).join(''):'<div class="empty-state"><h3>No reports yet</h3><p>Submit a lost or found report above. Your saved report will appear here for future matching.</p></div>'}
  function runLostFoundMatch(){if(!state.user)return showLogin();const f=new FormData($('#lostForm'));const report={id:`lf_${Date.now()}`,type:state.reportType,description:String(f.get('description')),color:String(f.get('color')),location:String(f.get('location')),date:String(f.get('date')||''),category:String(f.get('category')),author:state.user.name};state.lostFound.unshift(report);persist();const matches=state.lostFound.filter(x=>x.id!==report.id&&x.type!==report.type).map(x=>{const textA=`${report.description} ${report.color} ${report.location} ${report.category}`;const textB=`${x.description} ${x.color} ${x.location} ${x.category}`;return {...x,score:Math.round(similarity(textA,textB)*100)}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,5);$('#matchMeterFill').style.width=`${matches[0]?.score||0}%`;$('#matchExplanation').textContent=matches.length?`Best stored report match: ${matches[0].score}%. Shared words and context contributed to the rank.`:'No stored report was similar enough yet. Keep the report active and review future matches.';$('#matchStack').innerHTML=matches.length?matches.map(x=>`<article class="match-card glass-panel"><div><span class="section-kicker">${escapeHTML(x.type)} report</span><h3>${escapeHTML(x.description)}</h3><p>${escapeHTML(x.location)} · ${escapeHTML(x.category)}</p></div><strong>${x.score}%</strong></article>`).join(''):'<div class="empty-state"><h3>No likely matches yet</h3><p>Your report is saved. A future backend can notify you when new reports create a stronger match.</p></div>';addNotification('Lost & Found report saved','Your report is now stored locally for future matching.');toast('Report saved','Potential matches are suggestions only.','success')}

  async function hashPassword(password){if(window.crypto?.subtle){const data=new TextEncoder().encode(password);const digest=await crypto.subtle.digest('SHA-256',data);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')}let h=0;for(let i=0;i<password.length;i++)h=((h<<5)-h)+password.charCodeAt(i)|0;return `fallback_${Math.abs(h)}`}
