  function renderProfile(){const u=state.user;$('#navUserName').textContent=u?.name||'Guest';$('#profileBtn').textContent=initials(u?.name);$('#profileBtn').classList.toggle('hidden',!u);$('#guestAuthActions').classList.toggle('hidden',!!u);$('#profileAvatar').textContent=initials(u?.name);$('#profileTitle').textContent=u?.name||'Guest User';$('#profileCollege').textContent=u?`${u.college} · ${u.course}`:'Sign in or create an account to personalise UniTrade';$('#profileKarma').textContent=state.karma;$('#profileListings').textContent=u?state.listings.filter(x=>x.seller===u.name).length:0;$('#profileSaved').textContent=state.favorites.length;const extra=$('#profileExtraDetails');if(extra)extra.innerHTML=u?`<div class="profile-detail-grid"><div><small>Email</small><b>${escapeHTML(u.email||'Not added')}</b><span>${u.emailVerified?'Verified':'Optional'}</span></div><div><small>Phone</small><b>${escapeHTML(u.phone||'Not added')}</b><span>${u.phone?'Required · private':'Required'}</span></div><div><small>Course / department</small><b>${escapeHTML(u.course||'Not added')}</b><span>${escapeHTML(u.department||'')}</span></div><div><small>Study year</small><b>${escapeHTML(u.year||'Not added')}</b><span>${escapeHTML(u.hostel||'Campus area not added')}</span></div><div><small>Campus</small><b>${escapeHTML(u.college||'Not added')}</b><span>Full name or recognised acronym</span></div><div><small>City</small><b>${escapeHTML(u.city||'Not added')}</b><span>${escapeHTML(u.bio||'')}</span></div></div>`:'';$('#heroAccountActions').classList.toggle('hidden',!!u);syncHomeCounts()}

  function renderCommands(query=''){const q=query.toLowerCase().trim();const rows=COMMANDS.filter(x=>!q||x.join(' ').toLowerCase().includes(q));$('#paletteItems').innerHTML=rows.map(x=>`<button class="palette-item" data-command-route="${x[2]}"><b>${escapeHTML(x[0])}</b><small>${escapeHTML(x[1])}</small><span>↗</span></button>`).join('')||'<div class="empty-state compact"><h3>No commands found</h3></div>';$$('[data-command-route]').forEach(b=>b.addEventListener('click',()=>{closeCommandPalette();navigate(b.dataset.commandRoute)}))}
  function renderShortcuts(){const rows=[['/','Focus search'],['Ctrl/Cmd + K','Open command palette'],['T','Start the product tour'],['D','Toggle dark/light theme'],['N','Create a new listing'],['F','Open Marketplace filters'],['H','Home'],['M','Marketplace'],['A','About'],['?','Shortcuts'],['Escape','Close overlay'],['← / →','Move through the tour']];$('#shortcutList').innerHTML=rows.map(r=>`<div class="shortcut-row"><b>${escapeHTML(r[0])}</b><span>${escapeHTML(r[1])}</span></div>`).join('')}

  function updateSignupProgress(){const form=$('#signupForm');if(!form)return;const required=[...form.querySelectorAll('input[required]')];const done=required.filter(i=>i.type==='checkbox' ? i.checked : Boolean(String(i.value).trim())).length;$('#signupProgress').style.width=`${Math.round(done/required.length*100)}%`}
  function validateSignup(form){const f=new FormData(form);const name=String(f.get('name')).trim(),email=String(f.get('email')).trim().toLowerCase(),pass=String(f.get('password')),confirm=String(f.get('confirm'));if(!name||!email||!pass||!confirm||!f.get('college')||!f.get('course')||!f.get('year')||!f.get('hostel')||!f.get('phone'))return 'Complete all required fields.';if(!/^\S+@\S+\.\S+$/.test(email))return 'Enter a valid email address.';if(pass.length<8)return 'Password must be at least 8 characters.';if(pass!==confirm)return 'Passwords do not match.';if(!f.get('agree'))return 'Accept the responsible-use agreement to continue.';if(state.users.some(u=>u.email===email))return 'An account with this email already exists.';return ''}
