  async function createListing(form){if(!state.user){closeModal();return showLogin()}if(!cloudReady()||!cloudAuth().currentUser)return toast('Account connection unavailable','Firebase is not connected. Check the Firebase setup banner and firebase-config.js, then retry.','error');const f=new FormData(form);const price=Math.max(0,Number(f.get('price')||0));const original=Math.max(price,Number(f.get('originalPrice')||0));const listing={id:`l_${Date.now()}`,title:String(f.get('title')).trim(),price,originalPrice:original,category:String(f.get('category')),mode:String(f.get('mode')),condition:String(f.get('condition')),hostel:String(f.get('hostel')).trim(),distance:String(f.get('distance')).trim(),description:String(f.get('description')).trim(),seller:state.user.name,sellerInitials:initials(state.user.name),college:state.user.college||'',collegeShort:state.user.collegeShort||'',collegeKey:state.user.collegeKey||collegeKeyFor(state.user.college,state.user.collegeShort),created:new Date().toISOString().slice(0,10),availability:'Available',legacy:false,impactWeight: f.get('mode')==='free'?2:1,art:'✦',artTone:['cyan','violet','green','amber','magenta'][state.listings.length%5],tags:[]};if(!listing.title||!listing.description)return toast('Complete the listing','Add a title and description before publishing.','error');try{listing.ownerUid=cloudAuth().currentUser.uid;listing.status='active';listing.sellerDisplayName=state.user.name;listing.hostelLabel=listing.hostel;listing.id=await cloudWrite('listings',listing);}catch(err){console.error(err);return toast('Listing not saved',err.message||'Check Firebase configuration and rules.','error')}state.listings.unshift(listing);if(!state.favorites.includes(listing.id)){}persist();populateCategories();renderListings();renderProfile();renderImpact();renderCommunity();renderBundleCards();renderFireSale();form.reset();closeModal();navigate('marketplace');addKarma(listing.mode==='free'?20:10,listing.mode==='free'?'Free item shared':'Listing published');toast('Listing published','Your item is now visible in your marketplace.','success')}

